$editing=(int)($_GET['id']??0); $reservation=null;
if($editing){$s=$pdo->prepare("SELECT r.*,g.especial FROM reservas r JOIN grupos g ON g.id=r.grupo_id WHERE r.id=?");$s->execute([$editing]);$reservation=$s->fetch();if(!$reservation)redirect('index.php');}
if($_SERVER['REQUEST_METHOD']==='POST') {
 if(($_POST['action']??'')==='cancelar') { $id=(int)($_POST['id']??0); $by=$_SESSION['usuario_nome']??''; $reason=trim($_POST['motivo_cancelamento']??''); if(!$id || $by==='' || $reason==='') { flash('error','Não foi possível identificar o usuário logado ou o motivo.'); redirect('reserva_form.php?id='.$id); } $pdo->prepare("UPDATE reservas SET status='cancelado', cancelado_por=?, motivo_cancelamento=? WHERE id=?")->execute([$by,$reason,$id]); flash('success','Reserva cancelada e mantida para auditoria.'); redirect('index.php'); }
 try { $groupId=(int)$_POST['grupo_id'];$subIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['subgrupo_id']??[])))));$areaId=(int)$_POST['area_id'];$date=$_POST['data'];$time=$_POST['hora_inicio'];$endTime=$_POST['hora_fim']??'';$allDay=isset($_POST['dia_inteiro']);$recurrence=$_POST['recorrencia']??'nenhuma';$days=$_POST['dias_semana']??[];$until=$_POST['data_limite']?:null;$id=(int)($_POST['id']??0);
  if(!$subIds)throw new RuntimeException('Selecione ao menos um subgrupo.');
  $groupStatement=$pdo->prepare("SELECT especial FROM grupos WHERE id=? AND status='ativo'");$groupStatement->execute([$groupId]);$group=$groupStatement->fetch();if(!$group)throw new RuntimeException('Grupo ou subgrupo inválido.');$subCheck=$pdo->prepare("SELECT id FROM subgrupos WHERE id=? AND grupo_id=? AND status='ativo'");foreach($subIds as $subId){$subCheck->execute([$subId,$groupId]);if(!$subCheck->fetch())throw new RuntimeException('Grupo ou subgrupo inválido.');}
  if($allDay&&!$group['especial'])throw new RuntimeException('Somente grupos especiais podem fechar o dia.');if(!valid_time($time)||(!$allDay&&!valid_time($endTime))||!strtotime($date))throw new RuntimeException('Data ou horário inválido.');if(!$allDay&&$endTime<=$time)throw new RuntimeException('O horário de término deve ser depois do início.');if(!in_array(date('N',strtotime($date)),$allowed,true))throw new RuntimeException('Este dia não está permitido para reserva.');
  $start=(new DateTimeImmutable("$date $time"));$end=$allDay?(new DateTimeImmutable("$date {$config['hora_fim']}")):(new DateTimeImmutable("$date $endTime"));if($start->format('H:i')<$config['hora_inicio']||$end->format('H:i')>$config['hora_fim'])throw new RuntimeException('O horário deve estar dentro do período configurado.'); $dates=dates_for_recurrence($date,$recurrence,$days,$until);if(count($dates)>1&&$id)throw new RuntimeException('Edite uma reserva recorrente individualmente.');
    foreach($dates as $day){$itemStart="$day $time";$itemEnd=$allDay?"$day {$config['hora_fim']}":"$day $endTime";if(reservation_conflict($pdo,$areaId,$itemStart,$itemEnd,false,$id))throw new RuntimeException('Há conflito de horário em '.$day.'. Nenhuma reserva foi salva.');}
  $subCsv=implode(',',$subIds);$pdo->beginTransaction();if($id){$pdo->prepare('UPDATE reservas SET grupo_id=?,subgrupo_id=?,subgrupos_ids=?,area_id=?,data_inicio=?,data_fim=?,dia_inteiro=?,recorrencia=? WHERE id=?')->execute([$groupId,$subIds[0],$subCsv,$areaId,$start->format('Y-m-d H:i:s'),$end->format('Y-m-d H:i:s'),$allDay?1:0,'nenhuma',$id]);}else{$series=count($dates)>1?bin2hex(random_bytes(16)):null;$insert=$pdo->prepare('INSERT INTO reservas (grupo_id,subgrupo_id,subgrupos_ids,area_id,data_inicio,data_fim,dia_inteiro,criado_por,recorrencia,serie_id) VALUES (?,?,?,?,?,?,?,?,?,?)');foreach($dates as $day){$itemStart="$day $time";$itemEnd=$allDay?"$day {$config['hora_fim']}":"$day $endTime";$insert->execute([$groupId,$subIds[0],$subCsv,$areaId,$itemStart,$itemEnd,$allDay?1:0,$_SESSION['usuario_nome']??null,$recurrence,$series]);}}$pdo->commit();flash('success',$id?'Reserva atualizada.':'Reserva(s) criada(s) com sucesso.');redirect('index.php');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}
}
$groups=$pdo->query("SELECT * FROM grupos WHERE status='ativo' ORDER BY nome")->fetchAll();$areas=$pdo->query("SELECT * FROM areas WHERE status='ativo' ORDER BY nome")->fetchAll();
?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1"><?= $reservation?'Editar reserva':'Nova reserva' ?></h1></div><a class="btn btn-outline-secondary" href="index.php">Voltar</a></div><div class="row justify-content-center"><div class="col-lg-8"><div class="app-card"><form method="post" id="reservationForm"><input type="hidden" name="id" value="<?= $reservation['id']??'' ?>"><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Grupo</label><select class="form-select" name="grupo_id" id="group" required><option value="">Selecione</option><?php foreach($groups as $group): ?><option value="<?= $group['id'] ?>" data-special="<?= $group['especial'] ?>" <?= ($reservation['grupo_id']??'')==$group['id']?'selected':'' ?>><?= e($group['nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-4 mb-3"><label class="form-label">Área</label><select class="form-select" name="area_id" required><option value="">Selecione</option><?php foreach($areas as $area): ?><option value="<?= $area['id'] ?>" <?= ($reservation['area_id']??'')==$area['id']?'selected':'' ?>><?= e($area['nome']) ?> (<?= e($area['lugares']) ?> lugares)</option><?php endforeach; ?></select></div><div class="col-md-4 mb-3"><label class="form-label">Data</label><input class="form-control" type="date" name="data" required value="<?= isset($reservation)?date('Y-m-d',strtotime($reservation['data_inicio'])):date('Y-m-d') ?>"></div></div><div class="row"><div class="col-12 mb-3"><label class="form-label">Subgrupo</label><div id="subgroup" class="d-flex flex-wrap gap-3"></div></div></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Início</label><input class="form-control" type="time" name="hora_inicio" required value="<?= isset($reservation)?date('H:i',strtotime($reservation['data_inicio'])):substr($config['hora_inicio'],0,5) ?>"></div><div class="col-md-6 mb-3"><label class="form-label">Término</label><input class="form-control" type="time" name="hora_fim" id="endTime" required value="<?= isset($reservation)?date('H:i',strtotime($reservation['data_fim'])):'' ?>"></div></div><div class="form-check mb-3 d-none" id="allDayBox"><input class="form-check-input" type="checkbox" name="dia_inteiro" id="allDay" <?= ($reservation['dia_inteiro']??false)?'checked':'' ?>><label class="form-check-label" for="allDay">Fechar a agenda para o dia todo</label></div><?php if(!$reservation): ?><div class="border-top pt-3"><label class="form-label">Recorrência</label><select class="form-select mb-3" name="recorrencia" id="recurrence"><option value="nenhuma">Nenhuma</option><option value="semanal">Semanal</option><option value="mensal">Mensal</option></select><div id="repeatOptions" class="d-none"><div class="mb-3" id="weekdays"><?php foreach(['1'=>'Seg','2'=>'Ter','3'=>'Qua','4'=>'Qui','5'=>'Sex','6'=>'Sáb','7'=>'Dom'] as $n=>$label): ?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="dias_semana[]" value="<?= $n ?>"> <?= $label ?></label><?php endforeach; ?></div><label class="form-label">Data limite</label><input class="form-control" type="date" name="data_limite"></div></div><?php endif; ?><div class="alert alert-light border mt-3 mb-4" id="summary">Resumo: selecione grupo, subgrupo, área, data e horário.</div><?php if($reservation && $reservation['criado_por']): ?><p class="text-muted small mb-3">Reserva criada por: <strong><?= e($reservation['criado_por']) ?></strong></p><?php endif; ?><button class="btn btn-gold" type="submit">Confirmar reserva</button><?php if($reservation && $reservation['status']==='ativa'): ?><a class="btn btn-outline-danger ms-2" href="cancelar_reserva.php?id=<?= $reservation['id'] ?>">Cancelar reserva</a><?php endif; ?></form></div></div></div><script>const group=document.querySelector('#group'),subgroup=document.querySelector('#subgroup'),special=document.querySelector('#allDayBox'),recurrence=document.querySelector('#recurrence'),opts=document.querySelector('#repeatOptions'),saved=(('<?= $reservation['subgrupos_ids']??$reservation['subgrupo_id']??'' ?>')+'').split(',').filter(Boolean); async function loadSubs(){let id=group.value;subgroup.innerHTML='';if(!id)return;let data=await fetch('api_subgrupos.php?grupo_id='+id).then(r=>r.json());data.forEach(s=>{const label=document.createElement('label');label.className='form-check form-check-inline';const input=document.createElement('input');input.className='form-check-input';input.type='checkbox';input.name='subgrupo_id[]';input.value=s.id;if(saved.includes(String(s.id)))input.checked=true;label.appendChild(input);label.appendChild(document.createTextNode(' '+s.nome));subgroup.appendChild(label);});special.classList.toggle('d-none',group.selectedOptions[0]?.dataset.special!=='1');}group.addEventListener('change',loadSubs);recurrence?.addEventListener('change',()=>opts.classList.toggle('d-none',recurrence.value==='nenhuma'));loadSubs();</script><?php require __DIR__.'/includes/footer.php';
